import{_ as o,o as t,c as a,a4 as s}from"./chunks/framework.C83Ss68L.js";const u=JSON.parse('{"title":"ADR-0003: Framework adapters only on subpath exports","description":"Anything that imports a framework is published only through the exports map subpaths, with optional peers.","frontmatter":{"title":"ADR-0003: Framework adapters only on subpath exports","description":"Anything that imports a framework is published only through the exports map subpaths, with optional peers."},"headers":[],"relativePath":"explanation/decisions/adr-0003-adapter-subpath-exports.md","filePath":"explanation/decisions/adr-0003-adapter-subpath-exports.md","lastUpdated":1791568280000}'),r={name:"explanation/decisions/adr-0003-adapter-subpath-exports.md"};function d(n,e,i,c,p,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-0003-framework-adapters-only-on-subpath-exports" tabindex="-1">ADR-0003: Framework adapters only on subpath exports <a class="header-anchor" href="#adr-0003-framework-adapters-only-on-subpath-exports" aria-label="Permalink to &quot;ADR-0003: Framework adapters only on subpath exports&quot;">​</a></h1><p><strong>Status:</strong> Accepted · <strong>Date:</strong> 2026-09-20 (released in v4.0.0)</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Adapters import framework packages: <code>express</code>, <code>vue</code>, <code>react</code>, <code>svelte</code>, <code>solid-js</code>, <code>@angular/core</code>, <code>hono</code>, <code>better-auth</code>, <code>photoswipe</code>, Nuxt&#39;s <code>safe</code> conventions, and so on. If the main barrel re-exported them, a bare <code>import { useLogger } from &quot;katanakit-js&quot;</code> would drag peers into every bundle, every install would demand them, and the &quot;zero side effects on import&quot; guarantee would be impossible to defend.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Anything that imports a framework stays out of <code>src/index.ts</code> and is published <strong>only</strong> through the <code>exports</code> map as a subpath: <code>katanakit-js/adapters/express</code>, <code>/vue</code>, <code>/nuxt</code>, <code>/react</code>, <code>/svelte</code>, <code>/solid</code>, <code>/angular</code>, <code>/vanilla</code>, <code>/hono</code>, <code>/nestjs</code>, <code>/astro</code>, <code>/better-auth</code>, <code>/photoswipe</code>, <code>/notion</code>, <code>/wordpress</code>, <code>/insforge</code>, <code>/telegram</code>, <code>/whatsapp</code>, <code>/assistant</code>, plus <code>/prisma</code> and <code>/schemas</code>. Framework dependencies are <code>peerDependencies</code> with <code>peerDependenciesMeta.optional</code>, never <code>dependencies</code>. The <code>examples:check</code> script typechecks example projects against the built <code>dist/</code>, so a broken or missing subpath fails the build instead of reaching npm.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Better.</strong> The main bundle stays free of frameworks; consumers install only the peers they use; and the two guarantees that depend on this — zero side effects on import and a minimal install — hold without audit.</p><p><strong>Worse.</strong> The import path differs per adapter and there is no &quot;kitchen sink&quot; entry; nothing is discoverable from the main barrel, so docs must carry the map (the <a href="/katanakit-js/guides/getting-started#import-entry-points">entry-point list</a> is it). Adding an adapter means touching <code>package.json</code>, the docs and examples in the same change — by design, since that is the change the reviewer must see.</p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="/katanakit-js/guides/getting-started#import-entry-points">Getting Started — import entry points</a></li><li><a href="/katanakit-js/guides/architecture">Architecture</a> — the exports map in context.</li></ul>',11)])])}const m=o(r,[["render",d]]);export{u as __pageData,m as default};
